@RestController
@RequestMapping("/api/sheets/{sheetId}/crews")
@Validated
public class CrewController {

    /** What the screen shows of a crew: its name, its lead and its members in the order they were added. */
    public record CrewView(long id, String name, long leadId, List<Long> memberIds) {
        static CrewView of(Crew crew) {
            return new CrewView(crew.getId(), crew.getName(), crew.getLeadId(), crew.getMemberIds());
        }
    }

    public record CrewForm(@Size(max = 200) String name, Long leadId) {
    }

    public record MemberForm(Long personId) {
    }

    private final CrewService service;

    public CrewController(CrewService service) {
        this.service = service;
    }

    /** The sheet's crews in the order they were added. */
    @GetMapping
    public List<CrewView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        return service.list(sheetId.trim()).stream().map(CrewView::of).toList();
    }

    /** Add a crew. */
    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public CrewView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid CrewForm form) {
        return CrewView.of(service.add(sheetId.trim(), SignedInUser.name(user), form.name(), form.leadId()));
    }

    /** Add a member to a crew: the crew as it is then. */
    @PostMapping("/{crewId}/members")
    public CrewView addMember(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long crewId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid MemberForm form) {
        return CrewView.of(service.addMember(sheetId.trim(), SignedInUser.name(user), crewId, form.personId()));
    }
}
package net.officefloor.hq.app.crew;

import jakarta.persistence.CascadeType;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OneToMany;
import jakarta.persistence.OrderBy;
import jakarta.persistence.Table;
import java.util.ArrayList;
import java.util.List;

/** A crew of the sheet: a name, a lead and its members, each a person of the sheet. */
@Entity
@Table(name = "crew")
public class Crew {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "lead_id", nullable = false)
    private Long leadId;

    /** The members in the order they were added. */
    @OneToMany(cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.EAGER)
    @JoinColumn(name = "crew_id", nullable = false)
    @OrderBy("id ASC")
    private List<CrewMember> members = new ArrayList<>();

    protected Crew() {
    }

    public Crew(String sheetId, String name, long leadId) {
        this.sheetId = sheetId;
        this.name = name;
        this.leadId = leadId;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public Long getLeadId() {
        return leadId;
    }

    /** The members' person ids in the order they were added. */
    public List<Long> getMemberIds() {
        return members.stream().map(CrewMember::getPersonId).toList();
    }

    /** Whether the person is the lead or a member of the crew. */
    public boolean includes(long personId) {
        return leadId == personId || hasMember(personId);
    }

    public boolean hasMember(long personId) {
        return members.stream().anyMatch((m) -> m.getPersonId() == personId);
    }

    public void addMember(long personId) {
        members.add(new CrewMember(personId));
    }

    /** Give a person's place in the crew, as lead or member, to another person; a member place is dropped when
     *  that person is already in the crew, and on taking the lead they leave the members. */
    public void movePerson(long fromPersonId, long intoPersonId) {
        if (leadId == fromPersonId) {
            leadId = intoPersonId;
            members.removeIf((m) -> m.getPersonId() == intoPersonId);
        }
        for (CrewMember m : List.copyOf(members)) {
            if (m.getPersonId() != fromPersonId) continue;
            if (includes(intoPersonId)) members.remove(m);
            else m.setPersonId(intoPersonId);
        }
    }

    /** Take the person out of the crew's members; nothing when they are not one. */
    public void removeMember(long personId) {
        members.removeIf((m) -> m.getPersonId() == personId);
    }
}
